import{_ as d,o as e,c as l,a3 as a}from"./chunks/framework.B5WAEDB7.js";const p=JSON.parse('{"title":"自动驾驶项目交付与试点流程","description":"像建房子一样展示自动驾驶短途运输项目的场景调研、方案设计、集成、验证、试点和规模化过程。","frontmatter":{"title":"自动驾驶项目交付与试点流程","description":"像建房子一样展示自动驾驶短途运输项目的场景调研、方案设计、集成、验证、试点和规模化过程。","status":"设计建议","content_type":"delivery","keywords":["交付流程","试点","现场调研","集成","标定","验证","运营指标","证据包"],"scope":"WheelOS 短途自动驾驶运输项目的规划与交付方法","decision_summary":"把项目拆成可检查的阶段，每个阶段都有客户可见交付物、通过条件和未验证边界；未通过前一阶段不进入下一阶段。","best_for":["受控场景试点","固定路线运输","车辆和底盘集成","可量化运营指标"],"not_for":["跳过现场评估直接部署","未确认底盘就承诺运行","无证据即宣称量产"],"next_action":"从场景调研开始，明确任务、运行边界、车辆条件、验收指标和阶段负责人。","cta_url":"mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan"},"headers":[],"relativePath":"solutions/delivery-process.md","filePath":"solutions/delivery-process.md","lastUpdated":1794216847000}'),i={name:"solutions/delivery-process.md"};function r(o,t,s,h,n,c){return e(),l("div",null,[...t[0]||(t[0]=[a('<h1 id="自动驾驶项目交付与试点流程" tabindex="-1">自动驾驶项目交付与试点流程 <a class="header-anchor" href="#自动驾驶项目交付与试点流程" aria-label="Permalink to &quot;自动驾驶项目交付与试点流程&quot;">​</a></h1><blockquote><p>自动驾驶项目更适合像建房子一样推进：先勘察地基，再设计和施工，最后验收和入住。每一步都应该能看到成果、问题和证据，而不是先卖一个“成品”，再让客户承担集成风险。</p></blockquote><h2 id="客户看到的七个阶段" tabindex="-1">客户看到的七个阶段 <a class="header-anchor" href="#客户看到的七个阶段" aria-label="Permalink to &quot;客户看到的七个阶段&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>客户能看到什么</th><th>关键交付物</th><th>进入下一阶段的条件</th></tr></thead><tbody><tr><td>1. 场景调研</td><td>任务、班次、路线、货物、交接和当前成本</td><td>场景筛选表和初步价值测算</td><td>高频、可运营、有明确负责人</td></tr><tr><td>2. 边界设计</td><td>运行设计域、站点、路线、风险和法规问题</td><td>项目边界、责任矩阵和初步验收指标</td><td>风险可接受且责任明确</td></tr><tr><td>3. 车辆与传感器</td><td>底盘、传感器布局、计算平台和接口</td><td>硬件配置、接口清单和安装方案</td><td>线控和关键 CAN 信号可确认</td></tr><tr><td>4. 软件与数据集成</td><td>时间同步、坐标、定位、感知、规划和控制链路</td><td>配置、标定记录、数据记录和系统检查表</td><td>数据链路和基础功能可回放</td></tr><tr><td>5. 回放与受控场地验证</td><td>测试场景、指标、失败样本和问题清单</td><td>验证报告、失败案例和修复记录</td><td>达到约定阈值且边界清楚</td></tr><tr><td>6. 试点运行</td><td>每日任务、人员分工、异常处理和运营看板</td><td>运行日志、KPI、异常闭环和阶段总结</td><td>能稳定运营并按约定收集证据</td></tr><tr><td>7. 评估与扩展</td><td>是否具备复制条件、成本和风险</td><td>证据包、复盘和扩展建议</td><td>有可复核结果和明确剩余风险</td></tr></tbody></table><h2 id="每阶段都要-看得见" tabindex="-1">每阶段都要“看得见” <a class="header-anchor" href="#每阶段都要-看得见" aria-label="Permalink to &quot;每阶段都要“看得见”&quot;">​</a></h2><h3 id="客户可以要求查看" tabindex="-1">客户可以要求查看 <a class="header-anchor" href="#客户可以要求查看" aria-label="Permalink to &quot;客户可以要求查看&quot;">​</a></h3><ul><li>现场照片、路线图和运行设计域。</li><li>传感器与底盘接口清单。</li><li>时间同步、标定和数据记录检查结果。</li><li>回放数据、场景清单、指标和失败样本。</li><li>问题清单、修复记录和未解决风险。</li><li>试点运营看板和阶段复盘。</li></ul><h3 id="wheelos-应提供" tabindex="-1">WheelOS 应提供 <a class="header-anchor" href="#wheelos-应提供" aria-label="Permalink to &quot;WheelOS 应提供&quot;">​</a></h3><ul><li>明确的项目阶段和负责人。</li><li>每个阶段的输入、输出和验收条件。</li><li>标准配置、接口文档和测试记录格式。</li><li>技术风险、依赖和未验证边界。</li><li>可追溯的版本、配置和证据索引。</li></ul><h2 id="试点必须记录的指标" tabindex="-1">试点必须记录的指标 <a class="header-anchor" href="#试点必须记录的指标" aria-label="Permalink to &quot;试点必须记录的指标&quot;">​</a></h2><table tabindex="0"><thead><tr><th>指标</th><th>建议先定义的基线</th><th>用途</th></tr></thead><tbody><tr><td>运输频次</td><td>每日任务数、班次和高峰时段</td><td>判断真实需求和车辆利用率</td></tr><tr><td>人工投入</td><td>司机、搬运、调度和人工干预小时</td><td>与试点后的投入比较</td></tr><tr><td>车辆利用率</td><td>有效运行时间、等待时间和空驶时间</td><td>判断单车经济性</td></tr><tr><td>准点率</td><td>按约定时间窗口完成任务的比例</td><td>衡量业务可用性</td></tr><tr><td>异常次数</td><td>每百次任务的接管、急停、路径阻塞和人工恢复</td><td>识别系统与流程薄弱点</td></tr><tr><td>单位成本</td><td>每次任务、每公里或每个托盘的运营成本</td><td>判断商业可行性</td></tr><tr><td>安全事件</td><td>分级记录碰撞、险情、违规和现场风险</td><td>触发停机和整改</td></tr></tbody></table><p>这些是试点评价指标，不是 WheelOS 已实现的性能数据。只有在实际项目中记录并复核后，才能产生证据。</p><h2 id="不跳阶段" tabindex="-1">不跳阶段 <a class="header-anchor" href="#不跳阶段" aria-label="Permalink to &quot;不跳阶段&quot;">​</a></h2><ul><li>底盘和线控接口未确认，不进入车辆集成承诺。</li><li>时间同步、坐标和标定未检查，不进入路线性能结论。</li><li>没有回放和失败样本，不进入场地验证结论。</li><li>没有基线和运营指标，不进入商业效果结论。</li><li>没有完整证据记录，不把试点升级为“已验证”或量产能力。</li></ul><h2 id="试点结束时应形成的证据包" tabindex="-1">试点结束时应形成的证据包 <a class="header-anchor" href="#试点结束时应形成的证据包" aria-label="Permalink to &quot;试点结束时应形成的证据包&quot;">​</a></h2><ol><li>任务和运行设计域。</li><li>软件、配置、车辆和传感器版本。</li><li>原始日志、录包和关键回放。</li><li>基线、目标值、实际指标和统计方法。</li><li>异常、接管、失败样本和整改记录。</li><li>未覆盖场景、法规边界和剩余风险。</li><li>复核人和下一阶段建议。</li></ol><div class="solution-cta"><div><h2>先看项目如何一步步搭起来</h2><p>提交场景和车辆条件，我们会从调研、边界、集成、验证到试点逐阶段明确交付物和通过条件。</p></div><div class="solution-actions"><a class="primary" href="mailto:support@wheelos.cn?subject=WheelOS%20pilot%20delivery%20plan">讨论试点计划</a><a href="/solutions/applications">先评估应用场景</a></div></div>',17)])])}const b=d(i,[["render",r]]);export{p as __pageData,b as default};
